    "bid_management.award_confirm_title": "Igawad ang package na ito",
    "bid_management.award_no_leveling": "Hindi pa nakwenta ang leveling. Isaalang-alang ang pagpapatakbo ng Compute Leveling muna para batay sa naayos na score ang rekomendasyon.",
    "bid_management.awarded_amount": "Naigawad na halaga",
    "bid_management.awarded_amount_hint": "Pre-filled mula sa kabuuan ng column; ayusin kung may naaangkop na napagkasunduang figure.",
    "bid_management.awarded_bidder": "Naigawad na bidder",
    "bid_management.bid_recorded": "Naitala ang bid",
    "bid_management.confirm_award": "Kumpirmahin ang paggawad",
    "bid_management.decision_summary": "Buod ng desisyon",
    "bid_management.decision_summary_placeholder": "Bakit napili ang bidder na ito (napananatili sa rekord ng paggawad).",
